const trigger = $('Wenn von anderem Workflow aufgerufen').first().json;
const candidate = trigger.researchCandidateName;
const raw = $input.item.json;
const out = (raw.output && typeof raw.output === 'object') ? raw.output : raw;
const now = new Date().toISOString();

const news = Array.isArray(out.news) ? out.news.filter((entry) => typeof entry === 'string' && entry.trim().length > 0) : [];
const club = out.club || null;
const contract = out.contract || null;
const marketValue = out.marketValue || null;
const injuries = out.injuries || null;
const currentSituation = out.currentSituation || null;
const transferLikelihoodNotes = out.transferLikelihoodNotes || null;
const source = out.source || 'Websuche (Quelle nicht spezifiziert)';
const contractEndDateRaw = typeof out.contractEndDate === 'string' ? out.contractEndDate.trim() : null;
const contractEndDate = (contractEndDateRaw && /^\d{4}-\d{2}-\d{2}$/.test(contractEndDateRaw) && !Number.isNaN(Date.parse(contractEndDateRaw))) ? contractEndDateRaw : null;
const marketValueMEUR = (typeof out.marketValueMEUR === 'number' && Number.isFinite(out.marketValueMEUR)) ? out.marketValueMEUR : null;
let confidence = typeof out.confidence === 'number' ? out.confidence : 0;
if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));
const hasCoreFacts = Boolean(club) && Boolean(contract) && Boolean(marketValue) && Boolean(injuries) && news.length > 0;
const uncertain = !hasCoreFacts;
const researchResult = {candidate, club, contract, contractEndDate, marketValue, marketValueMEUR, injuries, currentSituation, transferLikelihoodNotes, news, source, timestamp: now, confidence: uncertain ? 0 : confidence, uncertain, uncertaintyReason: uncertain ? 'Websuche konnte nicht alle erforderlichen Angaben (Verein, Vertrag, Marktwert, Verletzungen, News) belastbar ermitteln.' : null};
return [{json: {...trigger, researchRuntimeBatchId: trigger.researchBatchId, researchRuntimeCandidate: candidate, researchRuntimeStatus: uncertain ? 'uncertain' : 'success', researchRuntimePayload: JSON.stringify(researchResult), researchRuntimeCompletedAt: now}}];

const trigger = $('Wenn von anderem Workflow aufgerufen').first().json;
const candidate = trigger.researchCandidateName || 'unbekannter Kandidat';
const current = $input.item.json || {};
const reason = (current.error && (current.error.message || current.error)) || 'Recherche-Agent konnte kein Ergebnis liefern.';
const now = new Date().toISOString();
const researchResult = {candidate, club: null, contract: null, contractEndDate: null, marketValue: null, marketValueMEUR: null, injuries: null, currentSituation: null, transferLikelihoodNotes: null, news: [], source: 'Websuche fehlgeschlagen (keine Quelle verfuegbar)', timestamp: now, confidence: 0, uncertain: true, uncertaintyReason: String(reason)};
return [{json: {...trigger, researchRuntimeBatchId: trigger.researchBatchId, researchRuntimeCandidate: candidate, researchRuntimeStatus: 'agent_error', researchRuntimePayload: JSON.stringify(researchResult), researchRuntimeCompletedAt: now}}];
